    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Set up: schedule and execute a simple operation so that cancel can be called on a pending operation
        bytes32 id = c.hashOperation(address(0), 0, "", bytes32(0), bytes32(0));
        c.schedule(address(0), 0, "", bytes32(0), bytes32(0), 1);
        vm.warp(block.timestamp + 2);
        // Execute the operation; reference _afterCall checks TIMELOCK_ADMIN_ROLE (msg.sender is address(this)), then sets timestamp to _DONE_TIMESTAMP
        c.execute{value: 0}(address(0), 0, "", bytes32(0), bytes32(0));
        // Cancel requires the operation to be pending (timestamp > _DONE_TIMESTAMP). After execution, it's done. So cancel will revert on reference; but we want to test supportsInterface difference via a scenario where cancel is callable
        // Instead, directly test supportsInterface after a state change that diverges: the mutant's supportsInterface returns false for IAccessControl, reference returns true
        bool refResult = c.supportsInterface(type(IAccessControl).interfaceId);
        assertTrue(refResult);
    }
}

