        // Actually, let's test supportsInterface directly after deploy:
        bool refResult = c.supportsInterface(bytes4(keccak256("IAccessControl")));
        assertTrue(refResult == true, "Reference should return true for IAccessControl");
        // On mutant, supportsInterface(IAccessControl) returns false, so this assertion will fail.
        // But we need to use a scenario that invokes cancel? No, the instruction says "the return value of P.supportsInterface(args) differs from that of M.supportsInterface(args)". So we can just call supportsInterface directly.
    }
}

