pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Grant EXECUTOR_ROLE to address(0) to make it an open role
        // The contract itself has TIMELOCK_ADMIN_ROLE, so it can set admin for EXECUTOR_ROLE
        // But we need to use the exposed interface: getRoleAdmin returns DEFAULT_ADMIN_ROLE (0x00)
        // and only DEFAULT_ADMIN_ROLE can grant EXECUTOR_ROLE's admin role.
        // Actually, constructor set EXECUTOR_ROLE admin to TIMELOCK_ADMIN_ROLE.
        // address(this) has TIMELOCK_ADMIN_ROLE. So we can call grantRole(EXECUTOR_ROLE, address(0))
        // using onlyRole(getRoleAdmin(EXECUTOR_ROLE)) which is TIMELOCK_ADMIN_ROLE.
        vm.prank(address(this));
        c.grantRole(c.EXECUTOR_ROLE(), address(0));

        // Now try to execute a simple operation as a random user (not admin).
        // In reference: hasRole(EXECUTOR_ROLE, address(0)) returns false, so onlyRoleOrOpenRole
        // calls _checkRole(EXECUTOR_ROLE, msg.sender) which reverts because msg.sender has no role.
        // In mutant: hasRole returns true, so open role check passes and execution proceeds.
        // This causes a divergent revert: reference reverts, mutant does not revert (but may later
        // revert on other checks, so we need to make it succeed to observe divergence).
        // We'll schedule a simple call first via a proposer, then execute it.

        // Grant PROPOSER_ROLE to address(this)
        vm.prank(address(this));
        c.grantRole(c.PROPOSER_ROLE(), address(this));

        // Schedule a simple call to self (just a dummy)
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = keccak256("test");
        uint256 delay = 1;
        vm.warp(block.timestamp + 100); // ensure timestamp after now
        vm.prank(address(this));
        c.schedule(target, value, data, predecessor, salt, delay);

        // Advance time to make operation ready
        vm.warp(block.timestamp + delay + 1);

        // Now execute as a random user
        address randomUser = address(0x1234);
        vm.prank(randomUser);
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "execute(address,uint256,bytes,bytes32,bytes32)",
                target, value, data, predecessor, salt
            )
        );

        // In reference, execute reverts (ok == false). In mutant, execute succeeds (ok == true)
        // because hasRole returns true for address(0), making the role open.
        // Actually, after execute, _afterCall checks TIMELOCK_ADMIN_ROLE which msg.sender doesn't have,
        // so mutant will also revert there. We need a different approach.
        // Let's instead check the revert boolean directly.

        // Re-do without scheduling to simplify: just check if execute reverts.
        // The observation: in reference, calling execute without being executor reverts;
        // in mutant, it does not revert (because open role).
        // But _afterCall still requires TIMELOCK_ADMIN_ROLE, so both revert. Need to bypass that.
        // We can observe the view function hasRole directly.

        bool result = c.hasRole(c.EXECUTOR_ROLE(), address(0));
        // Reference: false; Mutant: true
        assertTrue(result == false, "Reference expects false, mutant would give true");
    }
}

