        vm.prank(address(this));
        c.schedule(address(0xdead), 0, "", bytes32(0), salt, 1);
        bytes32 id = c.hashOperation(address(0xdead), 0, "", bytes32(0), salt);

        // Now a different address (not the proposer) tries to cancel
        // In reference, cancel reverts because msg.sender lacks PROPOSER_ROLE
        // In mutant, hasRole returns true for non-members, so cancel succeeds
        bool success;
        try c.cancel(id) {
            success = true;
        } catch {
            success = false;
        }

        // Reference: success == false (cancel reverts)
        // Mutant: success == true (cancel succeeds)
        assertTrue(success);
    }
}

