pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Grant EXECUTOR_ROLE to this contract so execute can be called
        c.grantRole(c.EXECUTOR_ROLE(), address(this));
        // Revoke TIMELOCK_ADMIN_ROLE from this contract to change the _afterCall behavior
        c.revokeRole(c.TIMELOCK_ADMIN_ROLE(), address(this));
        // Schedule an operation (needs PROPOSER_ROLE; this contract already has it via setup)
        bytes32 salt = 0x1234;
        bytes32 opId = c.hashOperation(address(this), 0, hex"", bytes32(0), salt);
        c.schedule(address(this), 0, hex"", bytes32(0), salt, 0);
        // Warp to make operation ready
        vm.warp(block.timestamp + 1);
        // Now execute; _afterCall will check hasRole(TIMELOCK_ADMIN_ROLE, address(this))
        // Reference: hasRole returns false -> revert
        // Mutant: hasRole returns true -> success, marking operation done
        bool ok;
        try c.execute(address(this), 0, hex"", bytes32(0), salt) {
            ok = true;
        } catch {
            ok = false;
        }
        // Assert that the operation is NOT done (reference reverts so stays pending) or IS done (mutant succeeds)
        // We assert the reference behavior: operation should NOT be done because execute reverts
        assertTrue(!c.isOperationDone(opId));
    }
}

