import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        bytes32 proposerRole = keccak256("PROPOSER_ROLE");
        bytes32 timelockAdminRole = keccak256("TIMELOCK_ADMIN_ROLE");

        // Schedule an operation as proposer
        bytes32 id = c.hashOperation(address(0xdead), 0, "", bytes32(0), bytes32(0x1234));
        vm.prank(address(this));
        c.schedule(address(0xdead), 0, "", bytes32(0), bytes32(0x1234), 1 days);

